const state={user:null,demo:false,config:{demo:false,houses:['Makkah','Al-Aqsa','Madinah'],targetLimits:{}},date:today(),kind:'quran',view:'daily',year:today().getFullYear(),expanded:false,data:{className:'My class',students:[],scores:{}},busy:false,save:'saved',tourStarted:false};
