const systemTheme=matchMedia('(prefers-color-scheme: dark)');
function applyTheme(theme){const dark=theme==='dark'||(theme==='system'&&systemTheme.matches);document.documentElement.dataset.theme=dark?'dark':'light';document.querySelector('meta[name="theme-color"]').content=dark?'#141a21':'#f5f7fa';}
applyTheme(localStorage.getItem('mysafar.theme')||'system');
systemTheme.addEventListener('change',()=>applyTheme(state.user?.theme||localStorage.getItem('mysafar.theme')||'system'));
async function api(path,options={}){const res=await fetch('/api'+path,{credentials:'same-origin',...options,headers:{'Content-Type':'application/json',...options.headers}});const body=await res.json().catch(()=>({error:'Cannot reach the server. Try again.'}));if(!res.ok)throw new Error(body.error||'Something went wrong. Try again.');return body;}
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),3200);}
function avatar(user,size=''){const src=user.photo||(user.avatarVersion?`/api/teachers/${encodeURIComponent(user.id)}/photo?v=${user.avatarVersion}`:null);return `<span class="avatar ${size}">${src?`<img src="${escape(src)}" alt="${escape(user.name)}">`:escape(initials(user.name))}</span>`;}
function demoData(){const students=['Adam Ibrahim','Aisha Ahmed','Yusuf Khan','Maryam Ali','Ibrahim Hassan','Fatima Noor','Omar Patel','Zainab Hussain'].map((name,i)=>({id:crypto.randomUUID(),name,house:state.config.houses[i%3]}));const data={version:2,className:'Class 4 · Al-Fatihah',students,scores:{}};for(let offset=-13;offset<=0;offset++)for(let i=0;i<students.length;i++){if(offset===0&&i>4)continue;data.scores[`${students[i].id}|${dayKey(addDays(today(),offset))}|quran`]=1+((i*3-offset)%5);if(i%2===0)data.scores[`${students[i].id}|${dayKey(addDays(today(),offset))}|memorisation`]={level:1+i%4,target:1+(i-offset)%9};}return data;}
function persistDemo(){localStorage.setItem(storageKey,JSON.stringify(state.data));}
function persistDemoProfile(){localStorage.setItem('mysafar.demo.profile',JSON.stringify(state.user));}
function startDemo(){
 state.demo=true;state.date=today();state.tourStarted=false;
 try{state.user=JSON.parse(localStorage.getItem('mysafar.demo.profile'))||{id:'demo',name:'Demo teacher',email:'',bio:'',theme:localStorage.getItem('mysafar.theme')||'system',onboardingCompleted:false};state.data=JSON.parse(localStorage.getItem(storageKey))||demoData();}catch{state.data=demoData();state.user={id:'demo',name:'Demo teacher',theme:'system',onboardingCompleted:false};}
 if(!Array.isArray(state.data.students))state.data=demoData();
 if(state.data.version!==2){localStorage.setItem(storageKey+'.legacy',JSON.stringify(state.data));state.data.students.forEach((s,i)=>{if(!state.config.houses.includes(s.house))s.house=state.config.houses[i%3];});state.data.scores=Object.fromEntries(Object.entries(state.data.scores).filter(([k])=>!k.endsWith('|memorisation')));state.data.students.forEach((s,i)=>{if(i%2===0)state.data.scores[`${s.id}|${dayKey(today())}|memorisation`]={level:1,target:4};});state.data.version=2;persistDemo();}
 state.view=state.data.students.length?'daily':'edit';applyTheme(state.user.theme);sessionStorage.setItem('mysafar.guest','1');render();
}
function renderAuth(){
 const signup=authMode==='signup';
 $('#app').innerHTML=`<main class="auth"><header class="auth-top">${logo()}<span class="branch">Enfield branch</span></header><div class="auth-body"><section class="auth-story"><h1>Tracking<br><span>made easy.</span></h1><p>Qur’an scores and memorisation targets.</p><div class="preview-art" aria-hidden="true"><div class="art-header"><span>Qur’an</span><span>${icon('check')}</span></div>${[0,1,2].map(i=>`<div class="art-row"><span class="art-avatar"></span><span class="art-name"></span>${[0,1,2,3,4].map(j=>`<span class="art-box ${j===4?'empty':'s'+(2+(i+j)%4)}">${j===4?'':2+(i+j)%4}</span>`).join('')}</div>`).join('')}</div></section><section class="auth-panel"><h2>${signup?'Create your account':'Welcome back.'}</h2><div class="auth-tabs" role="tablist" aria-label="Account access"><button role="tab" aria-selected="${!signup}" class="${!signup?'selected':''}" data-auth="login">Log in</button><button role="tab" aria-selected="${signup}" class="${signup?'selected':''}" data-auth="signup">Sign up</button></div><form id="auth-form">${signup?'<div class="field"><label for="teacher-name">Your name</label><input id="teacher-name" name="name" autocomplete="name" maxlength="80" required></div>':''}<div class="field"><label for="email">Email address</label><input id="email" name="email" type="email" autocomplete="email" placeholder="you@school.org" maxlength="254" required></div><div class="field"><label for="password">Password</label><div class="password-wrap"><input id="password" name="password" type="password" autocomplete="${signup?'new-password':'current-password'}" minlength="${signup?12:1}" maxlength="128" ${signup?'placeholder="At least 12 characters"':''} required><button type="button" class="icon-button" id="show-password" aria-label="Show password" aria-pressed="false">${icon('eye')}</button></div></div>${signup?'<div class="field"><label for="invite">Teacher access code</label><input id="invite" name="invite" autocomplete="off" placeholder="Your school’s access code" required></div>':''}<p id="auth-error" class="form-error" role="alert"></p><button class="primary auth-submit" type="submit">${signup?'Create account':'Log in'} ${icon('arrow')}</button></form>${state.config.demo?'<button class="text-button demo-button" id="demo-button">Open sample class</button>':''}</section></div></main>`;
 $$('[data-auth]').forEach(b=>b.onclick=()=>{authMode=b.dataset.auth;renderAuth();});
 $('#show-password').onclick=e=>{const p=$('#password');p.type=p.type==='password'?'text':'password';e.currentTarget.setAttribute('aria-pressed',p.type==='text');e.currentTarget.setAttribute('aria-label',p.type==='text'?'Hide password':'Show password');};
 $('#demo-button')?.addEventListener('click',startDemo);
 $('#auth-form').onsubmit=async e=>{e.preventDefault();const button=$('.auth-submit');button.disabled=true;$('#auth-error').textContent='';try{const result=await api('/auth/'+authMode,{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(e.target)))});state.user=result.user;state.demo=false;state.tourStarted=false;sessionStorage.removeItem('mysafar.guest');state.data=await api('/data');state.view=state.data.students.length?'daily':'edit';applyTheme(state.user.theme);render();}catch(err){$('#auth-error').textContent=err.message;button.disabled=false;}};
}
function navigateSection(view){if(view===state.view)return;if(state.view==='edit'&&state.data.students.length){confirmAction('Discard class changes?','Your unsaved edits will be lost.','Discard',()=>{state.view=view;render();});}else{state.view=view==='daily'&&!state.data.students.length?'edit':view;render();}}
function render(){
 if(!state.user)return renderAuth();
 const inTracker=['daily','calendar','edit'].includes(state.view);
 $('#app').innerHTML=`<div class="shell ${state.expanded?'expanded':''}"><aside class="sidebar">${logo()}<nav class="sidebar-nav" aria-label="Main navigation"><button class="nav-item ${inTracker?'selected':''}" data-nav="daily" aria-label="Tracker" title="Tracker">${icon('book')}<span>Tracker</span></button><button class="nav-item ${state.view==='teachers'?'selected':''}" data-nav="teachers" aria-label="Teachers" title="Teachers">${icon('users')}<span>Teachers</span></button></nav><div class="sidebar-bottom"><button class="nav-item" id="sidebar-toggle" title="${state.expanded?'Collapse':'Expand'} sidebar" aria-label="${state.expanded?'Collapse':'Expand'} sidebar" aria-expanded="${state.expanded}">${icon('panel')}<span>Collapse sidebar</span></button></div></aside><div class="workspace"><header class="topbar"><div class="mobile-brand">${logo()}</div><div class="desktop-context">${state.view==='teachers'?'Teachers':escape(state.data.className)}</div><div class="topbar-right"><span class="branch">Enfield branch</span><button class="account-button" data-profile aria-label="Open profile" aria-haspopup="dialog">${avatar(state.user)}</button></div></header><main class="content"><div id="main-view"></div></main></div><nav class="mobile-nav" aria-label="Mobile navigation"><button class="${inTracker?'selected':''}" data-nav="daily" aria-label="Tracker">${icon('book')}<span>Tracker</span></button><button class="${state.view==='teachers'?'selected':''}" data-nav="teachers" aria-label="Teachers">${icon('users')}<span>Teachers</span></button><button data-profile aria-label="Open profile" aria-haspopup="dialog">${avatar(state.user)}<span>Profile</span></button></nav></div>`;
 $('#sidebar-toggle').onclick=()=>{state.expanded=!state.expanded;$('.shell').classList.toggle('expanded',state.expanded);$('#sidebar-toggle').setAttribute('aria-expanded',state.expanded);$('#sidebar-toggle').setAttribute('aria-label',`${state.expanded?'Collapse':'Expand'} sidebar`);};
 $$('[data-nav]').forEach(b=>b.onclick=()=>navigateSection(b.dataset.nav));$$('[data-profile]').forEach(b=>b.onclick=openProfileMenu);
 if(state.view==='edit')renderEditor();else if(state.view==='teachers')renderTeachers();else renderTracker();
 if(!state.user.onboardingCompleted&&!state.tourStarted&&inTracker){state.tourStarted=true;requestAnimationFrame(()=>startTutorial());}
}
async function logout(){if(pendingSaves){toast('Wait for your changes to save.');return;}try{await saveQueue;if(!state.demo)await api('/auth/logout',{method:'POST',body:'{}'});$$('dialog[open]').forEach(d=>d.close());sessionStorage.removeItem('mysafar.guest');state.user=null;state.demo=false;state.view='daily';render();}catch(e){toast(e.message);}}
const scoreKey=(id,date,kind=state.kind)=>`${id}|${date}|${kind}`;
const scoreAt=(id,date)=>state.data.scores[scoreKey(id,date)];
const valueText=v=>v&&typeof v==='object'?`L${v.level}T${v.target}`:String(v||'');
function saveStatus(){const el=$('#save-status');if(el){el.innerHTML=`${icon(state.save==='failed'?'info':'check')}<span>${state.save==='saving'?'Saving…':state.save==='failed'?'Not saved':'Saved'}</span>`;el.classList.toggle('failed',state.save==='failed');}}
function renderTracker(){
 const cal=state.view==='calendar',count=state.data.students.filter(s=>scoreAt(s.id,dayKey(state.date))).length;
 $('#main-view').innerHTML=`<div class="mode-bar"><div class="segmented" role="tablist" aria-label="Tracker type"><button data-kind="quran" role="tab" aria-selected="${state.kind==='quran'}" class="${state.kind==='quran'?'selected':''}">${icon('book')} Qur’an</button><button data-kind="memorisation" role="tab" aria-selected="${state.kind==='memorisation'}" class="${state.kind==='memorisation'?'selected':''}">${icon('spark')} Memorisation</button></div><span class="save-status" id="save-status" role="status"></span></div><section class="tracker-card"><div class="card-toolbar"><div class="date-nav"><button class="icon-button" id="prev-day" aria-label="Previous ${cal?'year':'day'}">${icon('left')}</button><div class="date-display"><h1>${cal?state.year:format(state.date,{day:'numeric',month:'long',year:'numeric'})}</h1><span>${cal?'':format(state.date,{weekday:'long'})+(dayKey(state.date)===dayKey(today())?' · Today':'')}</span></div><button class="icon-button" id="next-day" aria-label="Next ${cal?'year':'day'}">${icon('right')}</button></div><div class="tools"><button class="today-button" id="today">Today</button><button class="icon-button ${cal?'active':''}" id="calendar-toggle" aria-label="${cal?'Return to tracker':'Open year calendar'}" title="Calendar">${icon(cal?'book':'calendar')}</button><button class="icon-button" id="edit-class" aria-label="Edit class" title="Edit class">${icon('edit')}</button></div></div><div id="tracker-view" class="view-enter">${cal?calendarMarkup():gridMarkup()}</div></section><div class="tracker-status"><span class="mobile-class">${escape(state.data.className)}</span><span>${cal?'':`${count} / ${state.data.students.length} recorded`}</span></div>`;
 saveStatus();$$('[data-kind]').forEach(b=>b.onclick=()=>{if(state.busy)return;state.kind=b.dataset.kind;renderTracker();});
 $('#prev-day').onclick=()=>navigate(-1);$('#next-day').onclick=()=>navigate(1);
 $('#today').onclick=()=>{if(cal){state.year=today().getFullYear();state.date=today();state.view='daily';renderTracker();}else changeDate(today());};
 $('#calendar-toggle').onclick=()=>transitionView(cal?'daily':'calendar');$('#edit-class').onclick=()=>{state.view='edit';render();};bindTracker();
}
function gridMarkup(){
 const days=Array.from({length:7},(_,i)=>addDays(state.date,i-3));
 const head=(date,i)=>`<div class="grid-head ${i===3?'focus-head':''}" data-date="${dayKey(date)}" data-label="${state.kind==='quran'?'Score':'Passed'}" data-distance="${Math.abs(i-3)}"><span>${format(date,{weekday:'short'})}</span><b>${String(date.getDate()).padStart(2,'0')}</b></div>`;
 const cell=(s,date,i)=>{const v=scoreAt(s.id,dayKey(date)),mem=state.kind==='memorisation';return `<div class="cell" data-date="${dayKey(date)}" data-distance="${Math.abs(i-3)}"><button class="score ${v?(mem?'passed':'s'+v):'empty'} ${i===3?'focus-score':''}" data-student="${s.id}" data-day="${dayKey(date)}" aria-label="${escape(s.name)}, ${format(date,{day:'numeric',month:'long'})}, ${v?(mem?valueText(v)+' passed':'score '+v+' of 5'):'no entry'}">${v?valueText(v):icon('plus')}</button></div>`;};
 return `<div class="mobile-week" aria-label="Week">${days.map((d,i)=>`<button data-week-day="${dayKey(d)}" class="${i===3?'selected':''}" data-distance="${Math.abs(i-3)}" aria-label="${format(d,{weekday:'long',day:'numeric',month:'long'})}" ${i===3?'aria-current="date"':''}><span>${format(d,{weekday:'short'})}</span><b>${d.getDate()}</b></button>`).join('')}</div><div class="table-scroll"><div class="score-grid" role="group" aria-label="${state.kind==='quran'?'Qur’an score':'Memorisation'} tracker">${days.slice(0,3).map(head).join('')}<div class="grid-head identity">Student</div>${head(days[3],3)}<div class="grid-head identity">House</div>${days.slice(4).map((d,i)=>head(d,i+4)).join('')}${state.data.students.map(s=>`${days.slice(0,3).map((d,j)=>cell(s,d,j)).join('')}<div class="cell identity"><span class="student-name">${escape(s.name)}</span></div>${cell(s,days[3],3)}<div class="cell identity house"><span class="house-pill h${state.config.houses.indexOf(s.house)}">${escape(s.house)}</span></div>${days.slice(4).map((d,j)=>cell(s,d,j+4)).join('')}`).join('')}</div></div>`;
}
function bindTracker(){
 $$('[data-student]').forEach(b=>b.onclick=()=>openScore(b.dataset.student,b.dataset.day));$$('[data-calendar-date]').forEach(b=>b.onclick=()=>{state.date=dateOf(b.dataset.calendarDate);transitionView('daily');});$$('[data-week-day]').forEach(b=>b.onclick=()=>changeDate(dateOf(b.dataset.weekDay)));
 let start=null;$('#tracker-view')?.addEventListener('touchstart',e=>{const t=e.touches[0];start={x:t.clientX,y:t.clientY};},{passive:true});$('#tracker-view')?.addEventListener('touchend',e=>{if(!start||state.view==='calendar')return;const t=e.changedTouches[0],dx=t.clientX-start.x,dy=t.clientY-start.y;start=null;if(Math.abs(dx)>65&&Math.abs(dx)>Math.abs(dy)*1.8)navigate(dx<0?1:-1);},{passive:true});
}
const reducedMotion=()=>matchMedia('(prefers-reduced-motion: reduce)').matches;
const animate=async(el,frames,options)=>{if(el&&!reducedMotion())await el.animate(frames,options).finished.catch(()=>{});};
async function transitionView(view){if(state.busy)return;state.busy=true;await animate($('#tracker-view'),[{opacity:1},{opacity:0}],{duration:140});state.view=view;if(view==='calendar')state.year=state.date.getFullYear();renderTracker();state.busy=false;}
function navigate(step){if(state.busy)return;if(state.view==='calendar'){state.year+=step;renderTracker();}else changeDate(addDays(state.date,step));}
async function changeDate(date){
 if(state.busy||dayKey(date)===dayKey(state.date)||date.getFullYear()<1900||date.getFullYear()>2199)return;state.busy=true;
 const oldPositions=new Map();$$('[data-date]').forEach(el=>oldPositions.set(el.dataset.date,el.getBoundingClientRect().left));await Promise.all($$('.score-grid .identity').map(el=>animate(el,[{opacity:1},{opacity:0}],{duration:90,fill:'forwards'})));
 const direction=date>state.date?1:-1;state.date=date;renderTracker();const mobile=matchMedia('(max-width:700px)').matches;
 const animations=$$('.score-grid [data-date]').map(el=>{const old=oldPositions.get(el.dataset.date);return animate(el,[{transform:`translateX(${mobile?direction*25:old===undefined?direction*35:old-el.getBoundingClientRect().left}px)`,opacity:0},{transform:'translateX(0)',opacity:getComputedStyle(el).opacity}],{duration:270,easing:'cubic-bezier(.22,.8,.3,1)'});});
 $$('.score-grid .identity').forEach(el=>animations.push(animate(el,[{opacity:0},{opacity:1}],{duration:150,delay:160,fill:'both'})));await Promise.all(animations);state.busy=false;
}
function calendarMarkup(){
 const recorded=new Set(Object.keys(state.data.scores).filter(k=>k.endsWith('|'+state.kind)).map(k=>k.split('|')[1]));
 return `<div class="calendar">${Array.from({length:12},(_,m)=>{const start=new Date(state.year,m,1,12),offset=(start.getDay()+6)%7,length=new Date(state.year,m+1,0).getDate(),cells=Math.ceil((offset+length)/7)*7;return `<section class="month ${m===today().getMonth()&&state.year===today().getFullYear()?'current':''}" aria-label="${format(start,{month:'long',year:'numeric'})}"><h2>${format(start,{month:'long'})}</h2><div class="month-days">${['M','T','W','T','F','S','S'].map(d=>`<span class="weekday">${d}</span>`).join('')}${Array.from({length:cells},(_,i)=>{const date=addDays(start,i-offset),key=dayKey(date);return `<button class="calendar-day ${date.getMonth()!==m?'other-month':''} ${key===dayKey(today())?'today':''} ${key===dayKey(state.date)?'chosen':''} ${recorded.has(key)?'has-data':''}" data-calendar-date="${key}" aria-label="${format(date,{day:'numeric',month:'long',year:'numeric'})}${recorded.has(key)?', records available':''}" ${key===dayKey(state.date)?'aria-current="date"':''}>${date.getDate()}</button>`;}).join('')}</div></section>`;}).join('')}</div>`;
}
function openScore(id,date){
 const student=state.data.students.find(s=>s.id===id),value=scoreAt(id,date),mem=state.kind==='memorisation';scoreContext={id,date,kind:state.kind};
 $('#score-dialog').innerHTML=`<div class="sheet-handle"></div><div class="dialog-top"><div><h2 id="score-title">${escape(student.name)}</h2><p>${format(dateOf(date),{day:'numeric',month:'long'})} · ${mem?'Memorisation':'Qur’an'}</p></div><button class="icon-button" data-close aria-label="Close entry">${icon('close')}</button></div>${mem?`<form id="pass-form"><div class="pass-fields"><div class="field"><label for="pass-level">Level</label><select id="pass-level">${Object.keys(state.config.targetLimits).map(l=>`<option value="${l}" ${Number(l)===(value?.level||1)?'selected':''}>Level ${l}</option>`).join('')}</select></div><div class="field"><label for="pass-target">Target</label><select id="pass-target"></select></div></div><button class="primary full" type="submit">${icon('check')} Record pass <span id="pass-code"></span></button></form>`:`<p class="field-label">Score</p><div class="score-options">${[1,2,3,4,5].map(n=>`<button class="score s${n}" data-score="${n}" aria-label="Score ${n} of 5" aria-pressed="${value===n}">${n}</button>`).join('')}</div>`}${value?'<button class="clear-score" id="clear-score">Clear entry</button>':''}`;
 $('[data-close]',$('#score-dialog')).onclick=()=>$('#score-dialog').close();$$('[data-score]').forEach(b=>b.onclick=()=>setScore(Number(b.dataset.score)));$('#clear-score')?.addEventListener('click',()=>setScore(null));
 if(mem){const updateCode=()=>{$('#pass-code').textContent=`L${$('#pass-level').value}T${$('#pass-target').value}`;};const updateTargets=()=>{const level=Number($('#pass-level').value),max=state.config.targetLimits[level];$('#pass-target').innerHTML=Array.from({length:max},(_,i)=>`<option value="${i+1}" ${value?.level===level&&value?.target===i+1?'selected':''}>Target ${i+1}</option>`).join('');updateCode();};$('#pass-level').onchange=updateTargets;$('#pass-target').onchange=updateCode;updateTargets();$('#pass-form').onsubmit=e=>{e.preventDefault();setScore({level:Number($('#pass-level').value),target:Number($('#pass-target').value)});};}
 $('#score-dialog').showModal();if(!mem)$(`[data-score="${value||1}"]`)?.focus();
}
const versions=new Map();
function setScore(value){
 const {id,date,kind}=scoreContext;$('#score-dialog').close();const key=scoreKey(id,date,kind),before=state.data.scores[key],version=(versions.get(key)||0)+1;versions.set(key,version);
 if(value===null)delete state.data.scores[key];else state.data.scores[key]=value;state.save='saving';pendingSaves++;renderTracker();
 saveQueue=saveQueue.then(async()=>{try{if(state.demo)persistDemo();else await api('/scores',{method:'PUT',body:JSON.stringify({studentId:id,date,kind,value})});state.save='saved';}catch(err){if(versions.get(key)===version){if(before===undefined)delete state.data.scores[key];else state.data.scores[key]=before;}state.save='failed';toast('Not saved. '+err.message);}finally{pendingSaves--;if(state.user&&['daily','calendar'].includes(state.view))renderTracker();saveStatus();}});
}
function renderEditor(){
 const existing=state.data.students.length>0;
 $('#main-view').innerHTML=`<section class="editor-card view-enter"><div class="section-title"><h1>${existing?'Edit class':'Set up your class'}</h1></div><form id="class-form"><div class="field"><label for="class-name">Class name</label><input id="class-name" name="className" maxlength="80" value="${escape(existing?state.data.className:'')}" placeholder="e.g. Class 4" required></div><div class="editor-labels"><span></span><span>Student</span><span>House</span><span></span></div><div id="student-entries"></div><button type="button" class="add-student" id="add-student">${icon('plus')} Add student</button><p class="form-error" id="class-error" role="alert"></p><div class="editor-actions"><span id="student-count"></span><div>${existing?'<button type="button" class="secondary" id="cancel-edit">Cancel</button>':''}<button class="primary" type="submit" id="save-class">Save changes ${icon('check')}</button></div></div></form></section>`;
 (existing?state.data.students:[{id:crypto.randomUUID(),name:'',house:''},{id:crypto.randomUUID(),name:'',house:''}]).forEach(appendStudent);
 $('#add-student').onclick=()=>{if($$('.student-entry').length>=200){toast('A class can have up to 200 students.');return;}appendStudent({id:crypto.randomUUID(),name:'',house:''});$$('.student-entry input').at(-1).focus();};
 $('#cancel-edit')?.addEventListener('click',()=>{state.view='daily';render();});
 $('#class-form').onsubmit=e=>{e.preventDefault();const students=$$('.student-entry').map(el=>({id:el.dataset.id,name:$('[name="student"]',el).value.trim(),house:$('[name="house"]',el).value}));if(!students.length){$('#class-error').textContent='Add at least one student.';return;}const removed=state.data.students.filter(s=>!students.some(n=>n.id===s.id));const save=()=>saveClass(students,$('#class-name').value.trim());if(removed.length)confirmAction('Remove students?',`${removed.length} student${removed.length===1?'':'s'} and their saved records will be permanently removed.`,'Remove and save',save);else save();};
}
function appendStudent(student){
 const entry=document.createElement('div');entry.className='student-entry';entry.dataset.id=student.id;entry.innerHTML=`<span class="row-no"></span><input name="student" value="${escape(student.name)}" placeholder="Full name" maxlength="80" required><select name="house" required><option value="">Choose house</option>${state.config.houses.map(h=>`<option ${h===student.house?'selected':''}>${h}</option>`).join('')}</select><button type="button" class="icon-button" aria-label="Remove student">${icon('close')}</button>`;$('button',entry).onclick=()=>{entry.remove();updateEntries();};$('#student-entries').append(entry);updateEntries();
}
function updateEntries(){$$('.student-entry').forEach((el,i)=>{$('.row-no',el).textContent=String(i+1).padStart(2,'0');$('[name="student"]',el).setAttribute('aria-label',`Student ${i+1} name`);$('[name="house"]',el).setAttribute('aria-label',`Student ${i+1} house`);});$('#student-count').textContent=`${$$('.student-entry').length} students`;}
async function saveClass(students,className){
 $('#save-class').disabled=true;$('#class-error').textContent='';try{await saveQueue;if(state.demo){state.data.students=students;state.data.className=className;const ids=new Set(students.map(s=>s.id));state.data.scores=Object.fromEntries(Object.entries(state.data.scores).filter(([k])=>ids.has(k.split('|')[0])));persistDemo();}else{await api('/class',{method:'PUT',body:JSON.stringify({className,students})});state.data=await api('/data');}state.view='daily';if(!state.user.onboardingCompleted)state.tourStarted=false;render();toast('Class saved.');}catch(err){$('#class-error').textContent=err.message;$('#save-class').disabled=false;}
}
async function updateProfile(changes){if(state.demo){Object.assign(state.user,changes);persistDemoProfile();}else{const result=await api('/profile',{method:'PUT',body:JSON.stringify(changes)});state.user=result.user;}return state.user;}
function openProfileMenu(){
 const dark=document.documentElement.dataset.theme==='dark';
 $('#profile-menu').innerHTML=`<div class="sheet-handle"></div><div class="profile-menu-head">${avatar(state.user,'large')}<div><h2 id="profile-menu-title">${escape(state.user.name)}</h2><span>Teacher · Enfield</span></div><button class="icon-button" id="close-menu" aria-label="Close profile menu">${icon('close')}</button></div><div class="menu-items"><button id="edit-profile">${icon('person')}<span>Edit profile</span>${icon('right')}</button><button id="view-teachers">${icon('users')}<span>Teachers</span>${icon('right')}</button><button id="theme-toggle" role="switch" aria-checked="${dark}" aria-label="Dark mode">${icon('moon')}<span>Dark mode</span><i class="switch ${dark?'on':''}"></i></button><button id="show-tutorial">${icon('help')}<span>Show tutorial</span>${icon('right')}</button><button id="logout">${icon('logout')}<span>Log out</span></button></div>`;
 $('#close-menu').onclick=()=>$('#profile-menu').close();$('#edit-profile').onclick=()=>{$('#profile-menu').close();openProfileEditor();};$('#view-teachers').onclick=()=>{$('#profile-menu').close();navigateSection('teachers');};
 $('#theme-toggle').onclick=async()=>{const prev=state.user.theme||'system',next=document.documentElement.dataset.theme==='dark'?'light':'dark';applyTheme(next);$('#theme-toggle').setAttribute('aria-checked',next==='dark');$('.switch').classList.toggle('on',next==='dark');try{await updateProfile({theme:next});localStorage.setItem('mysafar.theme',next);}catch(e){applyTheme(prev);toast(e.message);if($('#profile-menu').open){$('#theme-toggle').setAttribute('aria-checked',document.documentElement.dataset.theme==='dark');$('.switch').classList.toggle('on',document.documentElement.dataset.theme==='dark');}}};
 $('#show-tutorial').onclick=()=>{$('#profile-menu').close();if(state.view==='teachers'){state.view=state.data.students.length?'daily':'edit';render();}startTutorial();};
 $('#logout').onclick=()=>{if(state.view==='edit'){$('#profile-menu').close();confirmAction('Log out?','Your unsaved class edits will be lost.','Log out',logout);}else logout();};$('#profile-menu').showModal();
}
function openProfileEditor(){
 profileDraft={photo:null,remove:false};
 $('#profile-dialog').innerHTML=`<div class="sheet-handle"></div><div class="dialog-top"><h2 id="profile-title">Edit profile</h2><button class="icon-button" data-close aria-label="Close profile editor">${icon('close')}</button></div><form id="profile-form"><div class="photo-editor"><div id="photo-preview">${avatar(state.user,'profile-photo')}</div><div><button type="button" class="secondary" id="choose-photo">${icon('camera')} Change photo</button><button type="button" class="text-button" id="remove-photo" ${!state.user.photo&&!state.user.avatarVersion?'hidden':''}>Remove photo</button><input type="file" id="photo-input" accept="image/jpeg,image/png,image/webp" hidden></div></div><div class="field"><label for="profile-name">Name</label><input id="profile-name" maxlength="80" value="${escape(state.user.name)}" autocomplete="name" required></div><div class="field"><label for="profile-bio">About</label><textarea id="profile-bio" maxlength="280" rows="3" placeholder="Your role or subjects taught">${escape(state.user.bio||'')}</textarea></div><p class="form-error" id="profile-error" role="alert"></p><button class="primary full" id="save-profile" type="submit">Save profile</button></form>`;
 $('[data-close]',$('#profile-dialog')).onclick=()=>$('#profile-dialog').close();$('#choose-photo').onclick=()=>$('#photo-input').click();
 $('#remove-photo').onclick=()=>{profileDraft={photo:null,remove:true};$('#photo-preview').innerHTML=avatar({...state.user,photo:null,avatarVersion:0},'profile-photo');$('#remove-photo').hidden=true;};
 $('#photo-input').onchange=async e=>{const file=e.target.files[0];if(!file)return;const button=$('#save-profile');button.disabled=true;$('#profile-error').textContent='';try{if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>8*1024*1024)throw new Error('Choose a JPG, PNG or WebP photo under 8 MB.');const bitmap=await createImageBitmap(file);if(bitmap.width*bitmap.height>16000000){bitmap.close();throw new Error('Choose a photo smaller than 16 megapixels.');}const canvas=document.createElement('canvas');canvas.width=canvas.height=384;const side=Math.min(bitmap.width,bitmap.height);canvas.getContext('2d').drawImage(bitmap,(bitmap.width-side)/2,(bitmap.height-side)/2,side,side,0,0,384,384);bitmap.close();const photo=canvas.toDataURL('image/jpeg',.86);profileDraft={photo,remove:false};$('#photo-preview').innerHTML=avatar({...state.user,photo},'profile-photo');$('#remove-photo').hidden=false;}catch(err){$('#profile-error').textContent=err.message;}finally{button.disabled=false;}};
 $('#profile-form').onsubmit=async e=>{e.preventDefault();$('#save-profile').disabled=true;$('#profile-error').textContent='';try{const changes={name:$('#profile-name').value.trim(),bio:$('#profile-bio').value.trim()};if(state.demo){if(profileDraft.photo)changes.photo=profileDraft.photo;if(profileDraft.remove){changes.photo=null;changes.avatarVersion=0;}}else if(profileDraft.photo){await api('/profile/photo',{method:'PUT',body:JSON.stringify({image:profileDraft.photo})});}else if(profileDraft.remove){await api('/profile/photo',{method:'DELETE',body:'{}'});}await updateProfile(changes);$('#profile-dialog').close();render();toast('Profile saved.');}catch(err){$('#profile-error').textContent=err.message;$('#save-profile').disabled=false;}};
 $('#profile-dialog').showModal();
}
function renderTeachers(){
 $('#main-view').innerHTML=`<section class="directory"><div class="section-title"><h1>Teachers</h1></div>${state.demo?'<div class="empty-state"><p>Log in to view teachers.</p><button class="primary" id="directory-login">Log in</button></div>':`<label class="search-box">${icon('search')}<input id="teacher-search" type="search" aria-label="Search teachers" placeholder="Search teachers" autocomplete="off"></label><div id="teacher-list" class="teacher-list" aria-live="polite"></div><button class="secondary load-more" id="load-teachers" hidden>Load more</button>`}</section>`;
 if(state.demo){$('#directory-login').onclick=logout;return;}
 let query='',offset=0;
 const load=async(append=false)=>{const generation=++directoryGeneration;try{const result=await api('/teachers?q='+encodeURIComponent(query)+'&offset='+(append?offset:0));if(generation!==directoryGeneration||state.view!=='teachers')return;if(!append){$('#teacher-list').innerHTML='';offset=0;}offset+=result.teachers.length;if(!result.teachers.length&&!append)$('#teacher-list').innerHTML='<div class="empty-state">No teachers found.</div>';for(const teacher of result.teachers){const button=document.createElement('button');button.className='teacher-card';button.innerHTML=`${avatar(teacher,'large')}<span class="teacher-summary"><strong>${escape(teacher.name)}</strong><span>${escape(teacher.bio||'Teacher · '+teacher.branch)}</span></span>${icon('right')}`;button.onclick=()=>openTeacher(teacher);$('#teacher-list').append(button);}$('#load-teachers').hidden=!result.hasMore;}catch(err){if(generation===directoryGeneration&&$('#teacher-list')){$('#teacher-list').textContent=err.message;}}};
 $('#teacher-search').oninput=e=>{query=e.target.value;clearTimeout(searchTimer);directoryGeneration++;searchTimer=setTimeout(()=>load(),180);};$('#load-teachers').onclick=()=>load(true);load();
}
function openTeacher(teacher){$('#teacher-dialog').innerHTML=`<button class="icon-button corner-close" data-close aria-label="Close teacher profile">${icon('close')}</button><div class="teacher-detail">${avatar(teacher,'profile-photo')}<h2 id="teacher-title">${escape(teacher.name)}</h2><span>Teacher · Enfield branch</span>${teacher.bio?`<p>${escape(teacher.bio)}</p>`:''}</div>`;$('[data-close]',$('#teacher-dialog')).onclick=()=>$('#teacher-dialog').close();$('#teacher-dialog').showModal();}
function confirmAction(title,copy,button,callback){$('#confirm-dialog').innerHTML=`<h2 id="confirm-title">${escape(title)}</h2><p class="confirm-copy">${escape(copy)}</p><div class="confirm-actions"><button class="secondary" id="cancel-confirm">Cancel</button><button class="primary" id="accept-confirm">${escape(button)}</button></div>`;$('#cancel-confirm').onclick=()=>$('#confirm-dialog').close();$('#accept-confirm').onclick=()=>{$('#confirm-dialog').close();callback();};$('#confirm-dialog').showModal();$('#cancel-confirm').focus();}
function startTutorial(){
 if(!state.user||$('#tour-dialog').open)return;
 if(state.view==='edit'){tourSteps=[{target:'.editor-card',title:'Set up your class',copy:'Add your students and choose Makkah, Al-Aqsa or Madinah for each house. Use + to add more rows, then save.',setup:true}];}
 else{tourSteps=[{target:'.segmented',title:'Choose a tracker',copy:'Use Qur’an for a score from 1–5. Use Memorisation to record a passed level and target.'},{target:'.focus-score',title:'Record a result',copy:'Tap a student’s box. Select a score, or a level and target such as L1T4. Blank means no entry.'},{target:'.card-toolbar',title:'Move between dates',copy:'Use the arrows, select a calendar date, or swipe across the tracker on mobile. Today brings you back.'},{target:'#edit-class',title:'Update your class',copy:'Add students, change their house, or edit their names here.'},{target:matchMedia('(max-width:700px)').matches?'.mobile-nav':'[data-profile]',title:'Your profile and colleagues',copy:'Open your profile to change your photo or switch dark mode. Teachers opens the staff directory.'}];}
 tourStep=0;$('#tour-dialog').showModal();renderTour();
}
function renderTour(){
 const step=tourSteps[tourStep],target=$(step.target);if(!target){finishTour();return;}target.scrollIntoView({block:'nearest',behavior:'instant'});
 const r=target.getBoundingClientRect(),width=window.innerWidth,height=window.innerHeight;const left=Math.max(10,Math.min(width-326,r.left));const cardTop=r.bottom+18<height-245?r.bottom+18:Math.max(20,r.top-230);
 $('#tour-dialog').innerHTML=`<div class="tour-ring" style="left:${Math.max(4,r.left-5)}px;top:${Math.max(4,r.top-5)}px;width:${Math.min(width-8,r.width+10)}px;height:${r.height+10}px"></div><div class="tour-card" style="left:${left}px;top:${cardTop}px"><div class="tour-progress">${tourStep+1} / ${tourSteps.length}<button class="text-button" id="skip-tour">Skip</button></div><h2 id="tour-title">${step.title}</h2><p>${step.copy}</p><div class="tour-actions">${tourStep?'<button class="secondary" id="back-tour">Back</button>':''}<button class="primary" id="next-tour">${step.setup?'Set up class':tourStep===tourSteps.length-1?'Done':'Next'} ${icon('arrow')}</button></div></div>`;
 $('#skip-tour').onclick=()=>finishTour();$('#back-tour')?.addEventListener('click',()=>{tourStep--;renderTour();});$('#next-tour').onclick=()=>{if(step.setup){$('#tour-dialog').close();$('#class-name')?.focus();}else if(tourStep===tourSteps.length-1)finishTour();else{tourStep++;renderTour();}};$('#next-tour').focus();
}
async function finishTour(){ $('#tour-dialog').close();try{await updateProfile({onboardingCompleted:true});}catch(err){toast('Tutorial preference was not saved.');}}
$('#tour-dialog').addEventListener('cancel',e=>{e.preventDefault();finishTour();});
window.addEventListener('resize',()=>{if($('#tour-dialog').open)renderTour();});
$('#score-dialog').addEventListener('keydown',e=>{if(scoreContext?.kind==='quran'&&/^[1-5]$/.test(e.key)){e.preventDefault();setScore(Number(e.key));}});
for(const dialog of $$('dialog:not(#tour-dialog)'))dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close();}});
document.addEventListener('keydown',e=>{if(!state.user||!['daily','calendar'].includes(state.view)||$('dialog[open]')||['INPUT','TEXTAREA','SELECT'].includes(e.target.tagName))return;if(e.key==='ArrowLeft'){e.preventDefault();navigate(-1);}if(e.key==='ArrowRight'){e.preventDefault();navigate(1);}});
window.addEventListener('beforeunload',e=>{if(pendingSaves){e.preventDefault();e.returnValue='';}});
async function init(){try{state.config=await api('/config');const session=await api('/session');if(session.user){state.user=session.user;state.data=await api('/data');state.view=state.data.students.length?'daily':'edit';applyTheme(state.user.theme);}else if(state.config.demo&&sessionStorage.getItem('mysafar.guest')){startDemo();return;}}catch(error){state.config={demo:false,houses:['Makkah','Al-Aqsa','Madinah'],targetLimits:{}};renderAuth();$('#auth-error').textContent='Cannot connect to the server. Refresh to try again.';return;}render();}
init();
